class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        offset = 1800
        size = 2 * offset + 1
        dp = [[-1] * 2 for _ in range(size)]

        for x in nums:
            new_dp = [row[:] for row in dp]

            new_prod = x
            if new_prod > limit:
                new_prod = limit + 1
            s_new = x
            if -offset <= s_new <= offset:
                idx = s_new + offset
                if new_dp[idx][1] == -1 or new_prod > new_dp[idx][1]:
                    new_dp[idx][1] = new_prod

            for j in range(size):
                for p in range(2):
                    if dp[j][p] == -1:
                        continue
                    prod = dp[j][p] * x
                    if prod > limit:
                        prod = limit + 1
                    if p == 0:
                        s_new = j - offset + x
                        p_new = 1
                    else:
                        s_new = j - offset - x
                        p_new = 0
                    if -offset <= s_new <= offset:
                        idx_new = s_new + offset
                        if new_dp[idx_new][p_new] == -1 or prod > new_dp[idx_new][p_new]:
                            new_dp[idx_new][p_new] = prod
            dp = new_dp

        ans = -1
        idx_k = k + offset
        if 0 <= idx_k < size:
            for p in range(2):
                val = dp[idx_k][p]
                if val != -1 and val <= limit:
                    if val > ans:
                        ans = val
        return ans

class Solution:
    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)
        # Precompute prefix sums for nums and cost
        prefix_nums = [0] * (n + 1)
        prefix_cost = [0] * (n + 1)
        for i in range(1, n + 1):
            prefix_nums[i] = prefix_nums[i-1] + nums[i-1]
            prefix_cost[i] = prefix_cost[i-1] + cost[i-1]

        # Initialize dp array
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        for i in range(1, n + 1):
            for j in range(0, i):
                # Calculate cost for subarray from j to i-1 (0-indexed)
                # The cost is: (prefix_nums[i] + k * m) * (prefix_cost[i] - prefix_cost[j])
                # But as derived, the recurrence is:
                # dp[i] = min over j of { dp[j] + prefix_nums[i]*(prefix_cost[i]-prefix_cost[j]) + k*prefix_cost[i] }
                current_cost = dp[j] + prefix_nums[i] * (prefix_cost[i] - prefix_cost[j]) + k * prefix_cost[i]
                if current_cost < dp[i]:
                    dp[i] = current_cost

        return dp[n]

