    dir_vec = {
        'N': (-1, 0),
        'S': (1, 0),
        'W': (0, -1),
        'E': (0, 1)
    }

    # Precompute cumulative displacements P[0..n]
    P = [(0, 0)] * (n + 1)
    curr_r, curr_c = 0, 0
    for i in range(1, n + 1):
        dr, dc = dir_vec[S[i-1]]
        curr_r += dr
        curr_c += dc
        P[i] = (curr_r, curr_c)

    # Build first_occurrence dictionary for indices 1 to n
    first_occurrence = {}
    for i in range(1, n + 1):
        v = P[i]
        if v not in first_occurrence:
            first_occurrence[v] = i

    # Prepare the result string
    res = []
    for t in range(1, n + 1):
        # Option 1: initial smoke at (R, C)
        if P[t] == (R, C):
            res.append('1')
        else:
            # Option 2: smoke generated at some time g (1<=g<=t) such that P[g] = P[t] - (R, C)
            target = (P[t][0] - R, P[t][1] - C)
            if target in first_occurrence:
                g0 = first_occurrence[target]
                if g0 <= t:
                    res.append('1')
                else:
                    res.append('0')
            else:
                res.append('0')

    print("".join(res))

