class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count(n, s):
            if n <= 0:
                return 0
            digits = list(map(int, str(n)))
            memo = {}

            def dp(pos, tight, current_sum, current_prod_mod, started):
                if current_sum > s:
                    return 0
                if pos == len(digits):
                    if started and current_sum == s and current_prod_mod == 0:
                        return 1
                    return 0
                state = (pos, tight, current_sum, current_prod_mod, started)
                if state in memo:
                    return memo[state]
                total = 0
                upper = digits[pos] if tight else 9
                for d in range(0, upper + 1):
                    new_tight = tight and (d == upper)
                    if not started and d == 0:
                        total += dp(pos + 1, new_tight, current_sum, 1, False)
                    else:
                        new_started = True
                        new_sum = current_sum + d
                        if new_sum > s:
                            continue
                        new_prod_mod = (current_prod_mod * d) % s
                        total += dp(pos + 1, new_tight, new_sum, new_prod_mod, True)
                memo[state] = total
                return total

            return dp(0, True, 0, 1, False)

        total_beautiful = 0
        for s in range(1, 82):
            total_beautiful += count(r, s) - count(l - 1, s)
        return total_beautiful

