    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n < k:
            return [0] * n

        max_len = 0
        for w in words:
            if len(w) > max_len:
                max_len = len(w)

        prefix_counts = {}
        for w in words:
            for l in range(1, len(w) + 1):
                prefix = w[:l]
                prefix_counts[prefix] = prefix_counts.get(prefix, 0) + 1

        max1 = [0] * (max_len + 1)
        count_max1 = [0] * (max_len + 1)
        max2 = [0] * (max_len + 1)

        for prefix, freq in prefix_counts.items():
            l = len(prefix)
            if freq > max1[l]:
                max2[l] = max1[l]
                max1[l] = freq
                count_max1[l] = 1
            elif freq == max1[l]:
                count_max1[l] += 1
            else:
                if freq > max2[l]:
                    max2[l] = freq

        valid = [False] * (max_len + 1)
        for l in range(1, max_len + 1):
            if max1[l] >= k:
                valid[l] = True

        suffix_max = [-1] * (max_len + 2)
        for l in range(max_len, 0, -1):
            if valid[l]:
                suffix_max[l] = l
            else:
                suffix_max[l] = suffix_max[l + 1]

        ans = [0] * n
        for i in range(n):
            if n - 1 < k:
                ans[i] = 0
                continue
            word = words[i]
            L_word = len(word)
            candidate = suffix_max[L_word + 1] if L_word + 1 <= max_len else -1
            if candidate != -1:
                ans[i] = candidate
            else:
                res = 0
                for l in range(L_word, 0, -1):
                    prefix_str = word[:l]
                    freq = prefix_counts[prefix_str]
                    if count_max1[l] > 1:
                        new_max = max1[l]
                    else:
                        if freq == max1[l]:
                            new_max = max(max1[l] - 1, max2[l])
                        else:
                            new_max = max1[l]
                    if new_max >= k:
                        res = l
                        break
                ans[i] = res
        return ans

