class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        INF = n + 1

        pairs = []
        for a, b in conflictingPairs:
            L = min(a, b) - 1
            R = max(a, b) - 1
            pairs.append((L, R))

        min_R_arr = [INF] * n
        groups = {}
        for L, R in pairs:
            if L not in groups:
                groups[L] = []
            groups[L].append(R)
            if R < min_R_arr[L]:
                min_R_arr[L] = R

        suffix_min = [INF] * (n + 1)
        for i in range(n - 1, -1, -1):
            suffix_min[i] = min(min_R_arr[i], suffix_min[i + 1])

        total_full = 0
        for i in range(n):
            total_full += max(0, suffix_min[i] - i)

        max_sub = 0
        m = len(pairs)

        for k in range(m):
            L0, R0 = pairs[k]

            if L0 in groups:
                R_list = groups[L0]
                if len(R_list) == 1:
                    new_min = INF
                else:
                    new_min = min(r for r in R_list if r != R0)
            else:
                new_min = INF

            new_suffix_min = [0] * n
            if L0 < n:
                next_val = suffix_min[L0 + 1] if L0 + 1 < n else INF
                new_suffix_min[L0] = min(new_min, next_val)
                for i in range(L0 - 1, -1, -1):
                    new_suffix_min[i] = min(min_R_arr[i], new_suffix_min[i + 1])

            diff = 0
            for i in range(0, L0 + 1):
                old_val = suffix_min[i]
                new_val = new_suffix_min[i]
                diff += max(0, old_val - i) - max(0, new_val - i)

            new_total = total_full - diff
            if new_total > max_sub:
                max_sub = new_total

        return max_sub

