class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        # Helper function to get the perimeter coordinate for a point
        def get_perimeter(p):
            x, y = p
            if y == 0:
                return x
            elif x == side:
                return side + y
            elif y == side:
                return 2 * side + (side - x)
            else:  # x == 0
                return 3 * side + (side - y)

        # Map each point to (perimeter, original_point)
        perimeter_points = []
        for p in points:
            perimeter_points.append((get_perimeter(p), p))

        # Sort by perimeter coordinate
        perimeter_points.sort(key=lambda x: x[0])

        # Extract just the points in sorted order
        sorted_points = [p for _, p in perimeter_points]

        n = len(sorted_points)

        # Function to check if it's possible to select k points with min distance d
        def feasible(d):
            # Start with the first point
            count = 1
            last_x, last_y = sorted_points[0]
            for i in range(1, n):
                x, y = sorted_points[i]
                # Manhattan distance
                dist = abs(x - last_x) + abs(y - last_y)
                if dist >= d:
                    count += 1
                    last_x, last_y = x, y
                    if count >= k:
                        return True
            return count >= k

        # Binary search for the maximum d
        low, high = 0, 2 * side
        ans = 0
        while low <= high:
            mid = (low + high) // 2
            if feasible(mid):
                ans = mid
                low = mid + 1
            else:
                high = mid - 1

        return ans

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        # Split p into prefix, middle, suffix
        first_star = p.find('*')
        second_star = p.find('*', first_star + 1)
        prefix = p[:first_star]
        middle = p[first_star+1:second_star]
        suffix = p[second_star+1:]

        m1 = len(prefix)
        m2 = len(middle)
        m3 = len(suffix)

        # If the entire pattern is "**", then the empty substring matches.
        if m1 == 0 and m2 == 0 and m3 == 0:
            return 0

        # Helper function for KMP pattern matching
        def kmp_search(text, pattern):
            if not pattern:
                return list(range(len(text) + 1))
            m = len(pattern)
            n_text = len(text)
            if m > n_text:
                return []
            # Compute prefix function (pi array)
            pi = [0] * m
            k = 0
            for q in range(1, m):
                while k > 0 and pattern[k] != pattern[q]:
                    k = pi[k-1]
                if pattern[k] == pattern[q]:
                    k += 1
                pi[q] = k
            # Search for pattern in text
            q = 0
            occurrences = []
            for i in range(n_text):
                while q > 0 and pattern[q] != text[i]:
                    q = pi[q-1]
                if pattern[q] == text[i]:
                    q += 1
                if q == m:
                    occurrences.append(i - m + 1)
                    q = pi[q-1]
            return occurrences

        # Find occurrences of middle and suffix
        mid_occ = kmp_search(s, middle)
        suff_occ = kmp_search(s, suffix)

        # Precompute nxt array for middle: nxt[i] is the smallest k >= i such that s[k:k+m2] == middle
        nxt = [10**9] * (n + 1)
        if m2 == 0:
            for i in range(n + 1):
                nxt[i] = i
        else:
            occ_mid = [False] * n
            for pos in mid_occ:
                if pos < n:
                    occ_mid[pos] = True
            for i in range(n - 1, -1, -1):
                if occ_mid[i]:
                    nxt[i] = i
                else:
                    nxt[i] = nxt[i+1]

        # Find valid start indices for prefix
        if m1 == 0:
            valid_starts = list(range(0, n + 1))
        else:
            pref_occ = kmp_search(s, prefix)
            valid_starts = pref_occ

        import bisect
        min_len = 10**9

        for i in valid_starts:
            start_mid = i + m1
            if start_mid > n:
                continue

            if m2 == 0:
                required_j = start_mid
            else:
                k = nxt[start_mid]
                if k == 10**9:
                    continue
                required_j = k + m2

            if m3 == 0:
                if required_j <= n:
                    length = required_j - i
                    if length < min_len:
                        min_len = length
            else:
                idx = bisect.bisect_left(suff_occ, required_j)
                if idx < len(suff_occ):
                    j = suff_occ[idx]
                    length = j + m3 - i
                    if length < min_len:
                        min_len = length

        return min_len if min_len < 10**9 else -1

