class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        m = len(target)
        n_nums = len(nums)

        total_masks = 1 << m
        best_cost = [float('inf')] * total_masks

        for mask in range(1, total_masks):
            subset = []
            for j in range(m):
                if mask & (1 << j):
                    subset.append(target[j])

            lcm_val = 1
            for x in subset:
                lcm_val = lcm_val * x // math.gcd(lcm_val, x)

            min_cost = float('inf')
            for n in nums:
                rem = n % lcm_val
                cost = (lcm_val - rem) % lcm_val
                if cost < min_cost:
                    min_cost = cost
            best_cost[mask] = min_cost

        dp = [float('inf')] * total_masks
        dp[0] = 0

        for mask in range(1, total_masks):
            sub = mask
            while sub > 0:
                prev = mask ^ sub
                if dp[prev] != float('inf'):
                    total = dp[prev] + best_cost[sub]
                    if total < dp[mask]:
                        dp[mask] = total
                sub = (sub - 1) & mask

        return dp[total_masks - 1]

class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""

        INF = 10**9

        P = [[0] * (n + 1) for _ in range(26)]
        for c in range(26):
            for i in range(1, n + 1):
                char_code = ord(caption[i - 1]) - ord('a')
                P[c][i] = P[c][i - 1] + abs(char_code - c)

        dp = [[INF] * 26 for _ in range(n + 1)]
        for c in range(26):
            dp[0][c] = 0

        best1 = [None] * (n + 1)
        best2 = [None] * (n + 1)
        best1[0] = (0, 0)
        best2[0] = (0, 1)

        min_val = [(INF, -1)] * 26
        for c in range(26):
            min_val[c] = (0, 0)

        parent = [None] * (n + 1)

        for i in range(0, n):
            if i >= 2:
                j = i - 2
                for c in range(26):
                    if best1[j][1] != c:
                        prev_cost = best1[j][0]
                    else:
                        prev_cost = best2[j][0]
                    term = prev_cost - P[c][j]
                    if term < min_val[c][0]:
                        min_val[c] = (term, j)

            for c in range(26):
                if min_val[c][0] == INF:
                    continue
                total_cost = P[c][i + 1] + min_val[c][0]
                if total_cost < dp[i + 1][c]:
                    dp[i + 1][c] = total_cost
                    j = min_val[c][1]
                    if best1[j][1] != c:
                        prev_char = best1[j][1]
                    else:
                        prev_char = best2[j][1]
                    parent[i + 1][c] = (j, prev_char)

            min1 = INF
            min2 = INF
            char1 = -1
            char2 = -1
            for c in range(26):
                if dp[i + 1][c] < min1:
                    min2 = min1
                    char2 = char1
                    min1 = dp[i + 1][c]
                    char1 = c
                elif dp[i + 1][c] < min2:
                    min2 = dp[i + 1][c]
                    char2 = c
            best1[i + 1] = (min1, char1)
            best2[i + 1] = (min2, char2)

        min_total = INF
        best_char = -1
        for c in range(26):
            if dp[n][c] < min_total:
                min_total = dp[n][c]
                best_char = c
            elif dp[n][c] == min_total:
                if best_char == -1 or c < best_char:
                    best_char = c

        if min_total == INF:
            return ""

        res = []
        i = n
        c = best_char
        while i > 0:
            j, prev_char = parent[i][c]
            length = i - j
            res.append(chr(ord('a') + c) * length)
            i = j
            c = prev_char

        res.reverse()
        return "".join(res)

