class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        ans = 0
        for left in range(n):
            cost = 0
            last = nums[left]
            for right in range(left, n):
                if right > left:
                    if nums[right] < last:
                        cost += last - nums[right]
                    else:
                        last = nums[right]
                if cost > k:
                    break
                ans += 1
        return ans

