class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        n = len(intervals)
        ints = []
        for i, (l, r, w) in enumerate(intervals):
            ints.append((l, r, w, i))

        ints.sort(key=lambda x: (x[1], x[0]))

        ends = [x[1] for x in ints]

        prev = [-1] * n
        for i in range(n):
            pos = bisect.bisect_left(ends, ints[i][0])
            prev[i] = pos - 1

        dp = [[(-1, ())] * (n + 1) for _ in range(5)]

        for i in range(n + 1):
            dp[0][i] = (0, ())

        for k in range(1, 5):
            for i in range(1, n + 1):
                idx = i - 1
                best = dp[k][i-1]

                if k == 1:
                    w = ints[idx][2]
                    orig_idx = ints[idx][3]
                    new_state = (w, (orig_idx,))
                    if new_state[0] > best[0] or (new_state[0] == best[0] and new_state[1] < best[1]):
                        best = new_state
                else:
                    p = prev[idx]
                    if p >= 0:
                        prev_state = dp[k-1][p+1]
                        if prev_state[0] != -1:
                            w = ints[idx][2]
                            orig_idx = ints[idx][3]
                            new_weight = prev_state[0] + w
                            new_indices = prev_state[1] + (orig_idx,)
                            if new_weight > best[0] or (new_weight == best[0] and new_indices < best[1]):
                                best = (new_weight, new_indices)
                dp[k][i] = best

        result = (-1, ())
        for k in range(1, 5):
            state = dp[k][n]
            if state[0] > result[0] or (state[0] == result[0] and state[1] < result[1]):
                result = state

        return list(result[1])

class Solution:
    def countGoodArrays(self, n: int, m: int, k: int) -> int:
        mod = 10**9 + 7

        # If n is 1, then k must be 0, and the answer is m
        if n == 1:
            return m % mod

        # Total adjacent pairs is n-1
        total_pairs = n - 1

        # We need to choose k positions out of total_pairs to be equal
        # C(total_pairs, k)

        # Function to compute factorial modulo mod
        def factorial(x):
            res = 1
            for i in range(2, x+1):
                res = (res * i) % mod
            return res

        # Function to compute modular inverse using Fermat's little theorem
        def mod_inverse(a, mod):
            return pow(a, mod-2, mod)

        # Compute C(total_pairs, k) = fact[total_pairs] * inv(fact[k]) * inv(fact[total_pairs - k])
        num = factorial(total_pairs)
        den = (factorial(k) * factorial(total_pairs - k)) % mod
        combinations = (num * mod_inverse(den, mod)) % mod

        # Compute m * (m-1)^k mod mod
        # If m is 1, then (m-1) is 0. If k > 0, then 0^k is 0. If k==0, 0^0 is 1.
        if m == 1:
            if k == 0:
                ways = 1
            else:
                ways = 0
        else:
            ways = m * pow(m-1, k, mod) % mod

        return (combinations * ways) % mod

