class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def check(k):
            # Calculate the minimum flips needed to ensure no block of identical characters has length > k
            flips = 0
            i = 0
            while i < n:
                j = i
                while j < n and s[j] == s[i]:
                    j += 1
                length = j - i
                # For a block of length `length`, the number of flips needed is (length - 1) // k
                flips += (length - 1) // k
                i = j
            return flips <= numOps

        low, high = 1, n
        while low < high:
            mid = (low + high) // 2
            if check(mid):
                high = mid
            else:
                low = mid + 1
        return low

