from collections import defaultdict

class Solution:
    def subsequencesWithMiddleMode(self, nums: List[int]) -> int:
        mod = 10**9 + 7
        n = len(nums)
        total = 0

        for i in range(2, n - 2):
            left = nums[0:i]
            right = nums[i+1:]
            m = nums[i]

            freq_left = defaultdict(int)
            for x in left:
                freq_left[x] += 1
            freq_right = defaultdict(int)
            for x in right:
                freq_right[x] += 1

            L1 = freq_left[m]
            L0 = i - L1
            R1 = freq_right[m]
            R0 = len(right) - R1

            freq_left_non_m = defaultdict(int)
            for x in left:
                if x != m:
                    freq_left_non_m[x] += 1
            sum_sq_left = sum(f * f for f in freq_left_non_m.values())

            freq_right_non_m = defaultdict(int)
            for x in right:
                if x != m:
                    freq_right_non_m[x] += 1
            sum_sq_right = sum(f * f for f in freq_right_non_m.values())

            ways1 = 0
            if L1 >= 2 and R0 >= 2:
                ways1 = (ways1 + math.comb(L1, 2) * math.comb(R0, 2)) % mod
            if L1 >= 1 and L0 >= 1 and R1 >= 1 and R0 >= 1:
                ways1 = (ways1 + (L1 * L0) * (R1 * R0)) % mod
            if L0 >= 2 and R1 >= 2:
                ways1 = (ways1 + math.comb(L0, 2) * math.comb(R1, 2)) % mod
            if L1 >= 2 and R1 >= 1 and R0 >= 1:
                ways1 = (ways1 + math.comb(L1, 2) * (R1 * R0)) % mod
            if L1 >= 1 and L0 >= 1 and R1 >= 2:
                ways1 = (ways1 + (L1 * L0) * math.comb(R1, 2)) % mod
            if L1 >= 2 and R1 >= 2:
                ways1 = (ways1 + math.comb(L1, 2) * math.comb(R1, 2)) % mod

            ways2 = 0
            for x, count_x in freq_left_non_m.items():
                freq_x_right = freq_right_non_m.get(x, 0)
                term = ( (R0 - freq_x_right) ** 2 - (sum_sq_right - freq_x_right ** 2) ) // 2
                ways2 = (ways2 + L1 * count_x * term) % mod

            for y, count_y in freq_right_non_m.items():
                freq_y_left = freq_left_non_m.get(y, 0)
                term = ( (L0 - freq_y_left) ** 2 - (sum_sq_left - freq_y_left ** 2) ) // 2
                ways2 = (ways2 + R1 * count_y * term) % mod

            total = (total + ways1 + ways2) % mod

        return total

