class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter
        freq = Counter(s)
        n = len(s)
        ans = n  # worst case: delete all characters

        # Iterate over all possible target frequencies k from 1 to n
        for k in range(1, n + 1):
            D = 0  # total deletions needed (excess)
            I = 0  # total insertions needed (deficit)
            for f in freq.values():
                if f > k:
                    D += f - k
                else:
                    I += k - f
            # The cost for this k is max(D, I) because change operations can cover min(D, I) operations
            ans = min(ans, max(D, I))

        return ans

