    A = list(map(int, data[1:1+n]))

    max_val = 10**7
    cnt = [0] * (max_val + 1)
    for x in A:
        cnt[x] += 1

    unique_vals = []
    for x in range(1, max_val + 1):
        if cnt[x] > 0:
            unique_vals.append(x)

    exists = set(unique_vals)
    M = 2 * max_val
    ans = 0

    for m in range(1, M + 1, 2):
