import sys

def solve():
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    A = list(map(int, data[1:]))

    # Find the nearest greater element to the left for each element
    left_greater = [-1] * N
    stack = []
    for i in range(N):
        while stack and A[stack[-1]] <= A[i]:
            stack.pop()
        if stack:
            left_greater[i] = stack[-1]
        stack.append(i)

    # Find the nearest greater element to the right for each element
    right_greater = [N] * N
    stack = []
    for i in range(N-1, -1, -1):
        while stack and A[stack[-1]] <= A[i]:
            stack.pop()
        if stack:
            right_greater[i] = stack[-1]
        stack.append(i)

    # Compute prefix sums
    prefix_sum = [0] * (N+1)
    for i in range(N):
        prefix_sum[i+1] = prefix_sum[i] + A[i]

    # For each K, the answer is the sum of the segment between left_greater[K]+1 and right_greater[K]-1
    results = []
    for i in range(N):
        L = left_greater[i] + 1
        R = right_greater[i] - 1
        if L > R:
            results.append(A[i])
        else:
            results.append(prefix_sum[R+1] - prefix_sum[L])

    print(" ".join(map(str, results)))

if __name__ == "__main__":
    solve()

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        # If threshold is 0, then no edges (but threshold is positive, so min 1)
        # Create a mapping from value to index
        val_to_index = {val: i for i, val in enumerate(nums)}

        # DSU initialization
        parent = list(range(n))
        rank = [0] * n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]  # path compression
                x = parent[x]
            return x

        def union(x, y):
            rx, ry = find(x), find(y)
            if rx == ry:
                return
            # union by rank
            if rank[rx] < rank[ry]:
                parent[rx] = ry
            elif rank[rx] > rank[ry]:
                parent[ry] = rx
            else:
                parent[ry] = rx
                rank[rx] += 1

        # For each number in nums that is <= threshold, connect with its multiples
        for x in nums:
            if x > threshold:
                continue
            # iterate multiples: 2*x, 3*x, ... up to threshold
            m = 2 * x
            while m <= threshold:
                if m in val_to_index:
                    # union the index of x and the index of m
                    idx_x = val_to_index[x]
                    idx_m = val_to_index[m]
                    union(idx_x, idx_m)
                m += x

        # Count the number of connected components: number of unique roots
        components = set()
        for i in range(n):
            components.add(find(i))

        return len(components)
